// Downloads a cover image (jpeg/png/webp only, checked by content type and by
// magic bytes; at most 10 MB). Returns the bytes and a file extension.
export async function downloadCover(url: string) {
  if (!/^https?:\/\//i.test(url)) throw new Error('Invalid cover URL')
  const res = await request(url, COVER_TIMEOUT_MS)
  if (!res.ok || !res.body) throw new HttpError(res.status)
  const type = res.headers.get('content-type') ?? ''
  if (!/^image\/(jpeg|png|webp)\b/i.test(type)) {
    throw new Error('Cover is not a JPEG, PNG or WebP image')
  }
  if (Number(res.headers.get('content-length')) > MAX_COVER_BYTES) {
    throw new Error('Cover is too large')
  }

  const reader = res.body.getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  for (;;) {
    const { done, value } = await reader.read().catch(() => {
      throw new Error('Cover download failed')
    })
    if (done) break
    size += value.byteLength
    if (size > MAX_COVER_BYTES) {
      await reader.cancel().catch(() => {})
      throw new Error('Cover is too large')
    }
    chunks.push(value)
  }

  const data = Buffer.concat(chunks)
  const ext = SIGNATURES.find((s) => s.matches(data))?.ext
  if (!ext) throw new Error('Cover is not a JPEG, PNG or WebP image')
  return { data, ext }
}

export const googleBooks: MetadataProvider = {
  async search({ title, author, isbn }) {
    const q = isbn
      ? `isbn:${isbn}`
      : [title && `intitle:${title}`, author && `inauthor:${author}`]
          .filter(Boolean)
          .join(' ')
    const params = new URLSearchParams({
      q,
      maxResults: '10',
      printType: 'books',
    })
    if (config.googleBooksApiKey) params.set('key', config.googleBooksApiKey)

    let data: { items?: Volume[] }
    try {
      data = await fetchJson(`${BASE_URL}/volumes?${params}`)
    } catch (err) {
      // Keyless requests share one project whose daily quota is exhausted.
      if (err instanceof HttpError && err.status === 429) {
        throw new Error(
          config.googleBooksApiKey
            ? 'Quota exceeded'
            : 'Quota exceeded; set GOOGLE_BOOKS_API_KEY',
        )
      }
      throw err
    }

    return (data.items ?? []).map((item): Candidate => {
      const info = item.volumeInfo ?? {}
      const images = info.imageLinks ?? {}
      const date = info.publishedDate?.match(/^\d{4}(-\d{2}(-\d{2})?)?/)?.[0]
      return {
        provider: 'google',
        id: item.id,
        title: info.title ?? '',
        authors: info.authors ?? [],
        description: info.description
          ? htmlToText(info.description) || null
          : null,
        publisher: info.publisher ?? null,
        publishedDate: date ?? null,
        isbn: isbnOf(info.industryIdentifiers),
        language: info.language ?? null,
        series: null,
        seriesIndex: null,
        pageCount: info.pageCount || null,
        coverUrl: cleanImage(
          IMAGE_SIZES.map((size) => images[size]).find(Boolean),
        ),
        thumbnailUrl: cleanImage(images.thumbnail ?? images.smallThumbnail),
      }
    })
  },
}
