import { Link } from '@tanstack/react-router'
import { Check, ExternalLink, Store } from 'lucide-react'

import { BookCover } from '#/components/book-cover'
import type { DiscoverBook } from '#/lib/discover-functions'

// A scrolling row of Hardcover books. A book in the library opens its page;
// otherwise admins search the Market for it and users open it on Hardcover.
export function DiscoverRow({
  title,
  books,
  admin,
  detail,
}: {
  title: string
  books: DiscoverBook[]
  admin: boolean
  detail?: (book: DiscoverBook) => string
}) {
  if (books.length === 0) return null
  return (
    <section className="min-w-0">
      <h2 className="mb-3 text-lg font-semibold">{title}</h2>
      <ul className="-mx-4 flex snap-x scroll-px-4 gap-4 overflow-x-auto px-4 pb-2">
        {books.map((book) => (
          <li key={book.id} className="w-28 shrink-0 snap-start sm:w-32">
            <DiscoverCard book={book} admin={admin} detail={detail} />
          </li>
        ))}
      </ul>
    </section>
  )
}

function DiscoverCard({
  book,
  admin,
  detail,
}: {
  book: DiscoverBook
  admin: boolean
  detail?: (book: DiscoverBook) => string
}) {
  const body = (
    <>
      <BookCover
        {...book}
        className="transition-shadow group-hover:shadow-md"
      />
      <p className="mt-2 line-clamp-2 text-sm leading-snug font-medium">
        {book.title}
      </p>
      <p className="mt-0.5 flex items-center gap-1 text-xs text-muted-foreground">
        {book.libraryId ? (
          <>
            <Check className="size-3 shrink-0" /> In library
          </>
        ) : admin ? (
          <>
            <Store className="size-3 shrink-0" /> Find in Market
          </>
        ) : (
          <>
            <ExternalLink className="size-3 shrink-0" /> Hardcover
          </>
        )}
        {detail && <span className="ml-auto">{detail(book)}</span>}
      </p>
    </>
  )
  if (book.libraryId) {
    return (
      <Link
        to="/books/$bookId"
        params={{ bookId: book.libraryId }}
        className="group block"
      >
        {body}
      </Link>
    )
  }
  if (admin) {
    return (
      <Link
        to="/market"
        search={{ q: [book.title, book.authors[0]].filter(Boolean).join(' ') }}
        className="group block"
      >
        {body}
      </Link>
    )
  }
  return (
    <a href={book.url} target="_blank" rel="noreferrer" className="group block">
      {body}
    </a>
  )
}

