import { createFileRoute } from '@tanstack/react-router'
import { ExternalLink } from 'lucide-react'

import { BookGrid } from '#/components/book-grid'
import { DiscoverRow } from '#/components/discover-row'
import { useDeferred } from '#/hooks/use-deferred'
import { discoverAuthor, getAuthorBooks } from '#/lib/discover-functions'

export const Route = createFileRoute('/_app/authors/$name')({
  loader: ({ params }) => getAuthorBooks({ data: params.name }),
  head: ({ params }) => ({ meta: [{ title: `${params.name} · Bookserve` }] }),
  component: Author,
})

function Author() {
  const books = Route.useLoaderData()
  const { name } = Route.useParams()
  const { user } = Route.useRouteContext()
  const author = useDeferred(name, () => discoverAuthor({ data: name }))
  const missing = author?.books.filter((b) => !b.libraryId) ?? []
  const years =
    author?.born && `${author.born}–${author.died ?? ''}`.replace(/–$/, '')

  return (
    <main className="mx-auto max-w-6xl px-4 py-8">
      <h1 className="text-2xl font-semibold">{name}</h1>
      {author && (
        <div className="mt-2 max-w-prose text-sm text-muted-foreground">
          <p className="flex flex-wrap gap-x-3">
            {years && <span>{years}</span>}
            <a
              href={author.url}
              target="_blank"
              rel="noreferrer"
              className="flex items-center gap-1 hover:text-foreground"
            >
              Hardcover
              <ExternalLink className="size-3" />
            </a>
          </p>
          {author.bio && (
            <p className="mt-3 leading-relaxed whitespace-pre-line text-foreground">
              {author.bio}
            </p>
          )}
        </div>
      )}
      <section className="mt-8">
        <h2 className="mb-3 text-lg font-semibold">In your library</h2>
        {books.length ? (
          <BookGrid books={books} />
        ) : (
          <p className="text-sm text-muted-foreground">No books</p>
        )}
      </section>
      <div className="mt-10">
        <DiscoverRow
          title="Not in your library"
          books={missing}
          admin={user.role === 'admin'}
          grid
        />
      </div>
    </main>
  )
}

import { createFileRoute } from '@tanstack/react-router'
import { ExternalLink } from 'lucide-react'

import { BookGrid } from '#/components/book-grid'
import { DiscoverRow } from '#/components/discover-row'
import { useDeferred } from '#/hooks/use-deferred'
import { discoverSeries, getSeriesBooks } from '#/lib/discover-functions'

// `author` tells Hardcover which of several same-named series this is.
export const Route = createFileRoute('/_app/series/$name')({
  validateSearch: (search: Record<string, unknown>): { author?: string } => ({
    author: typeof search.author === 'string' ? search.author : undefined,
  }),
  loader: ({ params }) => getSeriesBooks({ data: params.name }),
  head: ({ params }) => ({ meta: [{ title: `${params.name} · Bookserve` }] }),
  component: Series,
})

const position = (n: number | null) => (n == null ? '' : `#${n}`)

function Series() {
  const books = Route.useLoaderData()
  const { name } = Route.useParams()
  const { author: authorParam } = Route.useSearch()
  const { user } = Route.useRouteContext()
  const author = authorParam ?? books[0]?.authors[0] ?? null
  const series = useDeferred(`${name}|${author}`, () =>
    discoverSeries({ data: { series: name, author } }),
  )
  const missing = series?.books.filter((b) => !b.libraryId) ?? []

  return (
    <main className="mx-auto max-w-6xl px-4 py-8">
      <h1 className="text-2xl font-semibold">{name}</h1>
      <p className="mt-1 flex flex-wrap gap-x-3 text-sm text-muted-foreground">
        {author && <span>{author}</span>}
        {series && (
          <a
            href={series.url}
            target="_blank"
            rel="noreferrer"
            className="flex items-center gap-1 hover:text-foreground"
          >
            Hardcover
            <ExternalLink className="size-3" />
          </a>
        )}
      </p>
      <section className="mt-8">
        <h2 className="mb-3 text-lg font-semibold">In your library</h2>
        {books.length ? (
          <BookGrid
            books={books}
            detail={(b) => position(b.seriesIndex) || b.authors.join(', ')}
          />
        ) : (
          <p className="text-sm text-muted-foreground">No books</p>
        )}
      </section>
      <div className="mt-10">
        <DiscoverRow
          title="Not in your library"
          books={missing}
          admin={user.role === 'admin'}
          detail={(b) => position((b as { position: number }).position)}
          grid
        />
      </div>
    </main>
  )
}

